/**
 * REPLAY OF A REAL RUN — the run page's own data path, driven by bytes a
 * server actually put on the wire.
 *
 * `fixtures/real-run-node-stream.json` is a RECORDING, not a hand-written
 * fixture: every frame is verbatim from `GET /runs/{id}/events/stream` for
 * workflow run 41ee2991-d944-4737-af98-c23281ef4385 (2026-08-21, a live agent
 * node answering with a fenced JSON quiz). It is regenerated by capturing that
 * SSE feed; nothing in it was authored by hand.
 *
 * What it pins, end to end: frames → assembler → the lane manager → the REAL
 * activeRequests reducer → `resolveProvisionalKindRender`, which is the exact
 * function `BlockRenderer` calls to decide whether a block renders
 * provisionally. If this passes, a run page filling in a live quiz is a
 * rendering concern only.
 */

import { configureStore } from "@reduxjs/toolkit";

import activeRequestsReducer from "@/features/agents/redux/execution-system/active-requests/active-requests.slice";
import { resolveProvisionalKindRender } from "@/features/content-ir/react/partial-kind-route";
import { RunLaneManager } from "../redux/lane-manager";
import { RenderBlockFrameAssembler } from "../transport/render-block-frames";
import type { NodeStreamEvent } from "../types";

import recorded from "./fixtures/real-run-node-stream.json";

const FRAMES = recorded as unknown as NodeStreamEvent[];
const RUN = "41ee2991-d944-4737-af98-c23281ef4385";
const KEY = "agent::root:0";

function replay() {
  const store = configureStore({
    reducer: { activeRequests: activeRequestsReducer },
    middleware: (getDefault) => getDefault({ serializableCheck: false }),
  });
  const manager = new RunLaneManager(store.dispatch as never);
  const assembler = new RenderBlockFrameAssembler();
  const snapshots: Array<Record<string, unknown> | undefined> = [];

  for (const frame of FRAMES) {
    if (frame.kind === "render_block") {
      const block = assembler.push(frame);
      if (!block) continue;
      manager.pushRenderBlock(RUN, KEY, block);
      manager.flushAll();
      const requestId = manager.getLaneRequestId(RUN, KEY)!;
      const stored =
        store.getState().activeRequests.byRequestId[requestId]?.renderBlocks[
          block.blockId
        ];
      if (stored) snapshots.push(stored.metadata);
    } else if (frame.kind === "chunk" || frame.kind === "reasoning") {
      manager.pushDelta(
        RUN,
        KEY,
        frame.kind,
        frame.delta,
        frame.block_shadowed === true,
      );
    }
  }
  manager.flushAll();
  const requestId = manager.getLaneRequestId(RUN, KEY)!;
  return { store, manager, requestId, snapshots };
}

describe("a real workflow run's typed partial kinds reach the run page", () => {
  it("is a recording of a real run, not a hand-written wire", () => {
    expect(FRAMES.length).toBeGreaterThan(100);
    expect(FRAMES.every((f) => f.run_id === RUN)).toBe(true);
    expect(FRAMES.some((f) => f.kind === "render_block")).toBe(true);
    // The server marked the text channel shadowed — the flag this whole
    // one-producer rule rests on.
    expect(
      FRAMES.filter((f) => f.kind === "chunk").every((f) => f.block_shadowed),
    ).toBe(true);
  });

  it("fills the quiz in provisionally, then swaps to the final value", () => {
    const { store, requestId } = replay();
    const request = store.getState().activeRequests.byRequestId[requestId];
    expect(request).toBeDefined();

    const quizBlockId = Object.keys(request.renderBlocks).find(
      (id) => request.renderBlocks[id].type === "quiz",
    );
    expect(quizBlockId).toBeDefined();

    // Every provisional render the page would have shown, in order.
    const renders = [];
    for (const metadata of replay().snapshots) {
      const provisional = resolveProvisionalKindRender(
        { blockId: quizBlockId!, blockIndex: 1, type: "quiz", status: "streaming", metadata },
        { streamActive: true },
      );
      if (provisional) renders.push(provisional);
    }
    expect(renders.length).toBeGreaterThan(3);
    expect(new Set(renders.map((r) => r.kind))).toEqual(new Set(["quiz_set"]));

    // It FILLED IN. Measured on list MEMBERSHIP, not byte size: the closer
    // truncates back to a safe point, so a snapshot can be a few bytes
    // SMALLER than the one before when a half-arrived key is dropped. What
    // the contract actually promises (law 6 — a partial may be incomplete,
    // never wrong) is that a value already shown never disappears.
    const counts = renders.map((r) => {
      const envelope = r.block.metadata?.__ir as
        | { root?: { value?: { multiple_choice?: unknown[] } } }
        | undefined;
      return envelope?.root?.value?.multiple_choice?.length ?? 0;
    });
    expect(counts[0]).toBeGreaterThan(0);
    expect(counts[counts.length - 1]).toBeGreaterThan(counts[0]);
    for (let i = 1; i < counts.length; i++) {
      expect(counts[i]).toBeGreaterThanOrEqual(counts[i - 1]);
    }

    // …and the FINAL stored block produces NO provisional render: the
    // terminal landed, so the block's own content is the truth and the swap
    // happens in one frame with no flicker.
    const finalBlock = request.renderBlocks[quizBlockId!];
    expect(finalBlock.status).toBe("complete");
    expect(
      resolveProvisionalKindRender(finalBlock, { streamActive: true }),
    ).toBeNull();
  });

  it("leaves no stranded skeleton once the lane settles", () => {
    const { store, manager, requestId } = replay();
    manager.settleLane(RUN, KEY, "complete");
    const request = store.getState().activeRequests.byRequestId[requestId];
    for (const block of Object.values(request.renderBlocks)) {
      expect(
        resolveProvisionalKindRender(block, { streamActive: false }),
      ).toBeNull();
    }
  });

  it("stores ONE set of blocks — the server's, never a second parse", () => {
    const { store, requestId } = replay();
    const request = store.getState().activeRequests.byRequestId[requestId];
    // Every block id carries the server's per-run prefix; a block minted by
    // the frontend accumulator would not.
    for (const id of request.renderBlockOrder) {
      expect(id).toMatch(/^run_[0-9a-f]{12}:blk_\d+$/);
    }
  });
});
